/**
 * Login Component (Standalone)
 */

import { Component, OnInit, ViewChild, ElementRef, AfterViewInit } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { AuthService } from '@core/services/auth.service';
import { environment } from '@env/environment';

declare var google: any;

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterLink],
  templateUrl: './login.component.html',
  styleUrls: ['../auth.common.css'],
})
export class LoginComponent implements OnInit {
  @ViewChild('googleSignInButton') googleSignInButton!: ElementRef;

  loginForm!: FormGroup;
  loading = false;
  error = '';

  constructor(
    private formBuilder: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initializeForm();
    this.initializeGoogleSignIn();
  }

  private initializeForm(): void {
    this.loginForm = this.formBuilder.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
    });
  }

  private initializeGoogleSignIn(): void {
    this.waitForGoogleLibrary(() => {
      google.accounts.id.initialize({
        client_id: environment.googleClientId,
        callback: (response: any) => this.handleGoogleSignIn(response),
      });

      google.accounts.id.renderButton(this.googleSignInButton?.nativeElement, {
        theme: 'outline',
        size: 'large',
      });
    });
  }

  private waitForGoogleLibrary(callback: () => void, attempts = 0): void {
    const maxAttempts = 50; // 5 seconds max (50 * 100ms)

    if (attempts > maxAttempts) {
      console.error('Google Sign-In library failed to load');
      return;
    }

    if (typeof google !== 'undefined' && google.accounts && google.accounts.id) {
      callback();
    } else {
      setTimeout(() => {
        this.waitForGoogleLibrary(callback, attempts + 1);
      }, 100);
    }
  }

  private handleGoogleSignIn(response: any): void {
    if (!response.credential) {
      this.error = 'Google sign-in failed';
      return;
    }

    this.loading = true;
    this.error = '';

    this.authService.googleLogin(response.credential).subscribe({
      next: () => {
        // Increase delay to ensure cookies are fully set and guard can verify
        setTimeout(() => {
          this.router.navigate(['/dashboard/editor']).catch((err) => {
            this.error = 'Navigation failed';
            this.loading = false;
          });
        }, 300);
      },
      error: (error: any) => {
        this.error = error.error?.message || error.error?.error?.message || 'Google sign-in failed';
        this.loading = false;
      },
    });
  }

  onSubmit(): void {
    if (!this.loginForm.valid) return;

    this.loading = true;
    this.error = '';
    const { email, password } = this.loginForm.value;

    this.authService.login(email, password).subscribe({
      next: () => {
        this.router.navigate(['/dashboard/editor']);
      },
      error: (error: any) => {
        this.error = error.error?.message || error.error?.error?.message || 'Login failed';
        this.loading = false;
      },
    });
  }
}
<div class="auth-container">
  <div class="auth-card">
    <h1>CodeRank</h1>
    <h2>Login</h2>

    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label for="email">Email</label>
        <input
          type="email"
          id="email"
          formControlName="email"
          placeholder="Enter your email"
        />
        <span class="error" *ngIf="loginForm.get('email')?.hasError('required')">
          Email is required
        </span>
      </div>

      <div class="form-group">
        <label for="password">Password</label>
        <input
          type="password"
          id="password"
          formControlName="password"
          placeholder="Enter your password"
        />
        <span class="error" *ngIf="loginForm.get('password')?.hasError('required')">
          Password is required
        </span>
      </div>

      <button type="submit" [disabled]="!loginForm.valid || loading">
        {{ loading ? 'Logging in...' : 'Login' }}
      </button>

      <p class="error" *ngIf="error">{{ error }}</p>
    </form>

    <div class="divider">
      <span>OR</span>
    </div>

    <!-- Google Sign-In Button -->
    <div #googleSignInButton class="google-signin-container"></div>

    <p class="signup-link">
      Don't have an account? <a routerLink="/auth/register">Sign up</a>
    </p>
  </div>
</div>
